INSERT INTO `galleries` VALUES (1,'Radiant Reflections','A stunning collection of images capturing the essence of modern design and natural beauty.',1,0,'beauty/galleries/1.jpg',1,'published','2026-10-03 15:31:15','2026-10-03 15:31:15'),(2,'Glamour Grove','Discover breathtaking visuals that inspire and captivate the imagination.',1,0,'beauty/galleries/2.jpg',1,'published','2026-10-03 15:31:15','2026-10-03 15:31:15'),(3,'Serene Styles Showcase','A stunning collection of images capturing the essence of modern design and natural beauty.',1,0,'beauty/galleries/3.jpg',1,'published','2026-10-03 15:31:15','2026-10-03 15:31:15'),(4,'Allure Alcove','A stunning collection of images capturing the essence of modern design and natural beauty.',1,0,'beauty/galleries/4.jpg',1,'published','2026-10-03 15:31:15','2026-10-03 15:31:15'),(5,'Glamour Galleria','Discover breathtaking visuals that inspire and captivate the imagination.',1,0,'beauty/galleries/5.jpg',1,'published','2026-10-03 15:31:15','2026-10-03 15:31:15'),(6,'Beauty Boulevard','Premium quality images showcasing craftsmanship and attention to detail.',1,0,'beauty/galleries/6.jpg',1,'published','2026-10-03 15:31:15','2026-10-03 15:31:15');
